#include <chrono>
#include <iostream>
namespace speedprof {
enum Kind {ROOT, PRIOR, LEAF, FEATURES, TREE, CTM_PREPARE, CTM_SAMPLE_APPLY, LEAF_POLICY, V4_DECK, V4_STATE, COUNT};
inline const char* names[] = {"root_other","prior","leaf_other","rich_features","tree_predict","ctm_prepare","ctm_sample_apply","leaf_policy","v4_deck","v4_state"};
struct Scope;
inline thread_local Scope* top=nullptr;
inline thread_local double inclusive[COUNT]={},exclusive[COUNT]={};
inline thread_local unsigned long long calls[COUNT]={};
struct Scope {
 Kind kind; Scope* parent; bool on; double child=0; std::chrono::steady_clock::time_point start;
 explicit Scope(Kind k):kind(k),parent(top),on(k==ROOT || top) {if(on){start=std::chrono::steady_clock::now();top=this;++calls[k];}}
 ~Scope(){if(on){double dt=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();inclusive[kind]+=dt;exclusive[kind]+=dt-child;top=parent;if(parent)parent->child+=dt;}}
};
inline void dump(){for(int i=0;i<COUNT;++i)std::cerr<<"SPEED_PROFILE "<<names[i]<<" calls="<<calls[i]<<" inclusive="<<inclusive[i]<<" exclusive="<<exclusive[i]<<"\n";}
}

