#define main frozenParityMain
#include "../../apps/one_combat_tree_test.cpp"
#undef main
#include <chrono>
#include <sstream>
#include <cstdlib>
volatile double sink = 0;
int main() {
    sts::GameContext gc(sts::CharacterClass::IRONCLAD, 126700, 0);
    one_combat::PathHistory path;
    std::vector<std::vector<float>> states;
    for (int i=0;i<128;++i) { gc.gold=i*10;gc.curHp=i%81;gc.floorNum=i%55;states.push_back(one_combat::richFeatureVec(gc,path)); }
    auto timing = [&](auto fn) {
        const auto start=std::chrono::steady_clock::now();
        for(int i=0;i<10000;++i) sink=fn(i);
        return std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();
    };
    for (auto file : {"models/v_win_trees.txt", "models/v_rich_trees.txt"}) {
        LegacyTreeNet old;one_combat::CompactTreeNet current;
        if(!old.load(file,one_combat::richIdxMap(),"legacy") || !current.load(file,one_combat::richIdxMap()))return 1;
        for(int r=0;r<5;++r) {
            double a,b;
            double (LegacyTreeNet::* volatile oldPredict)(const std::vector<float> &) const = &LegacyTreeNet::predict;
            double (one_combat::CompactTreeNet::* volatile newPredict)(const std::vector<float> &) const = &one_combat::CompactTreeNet::predict;
            auto oldCall=[&](int i){return (old.*oldPredict)(states[i%128]);};
            auto newCall=[&](int i){return (current.*newPredict)(states[i%128]);};
            if(r%2){b=timing(newCall);a=timing(oldCall);}else{a=timing(oldCall);b=timing(newCall);}
            std::cout<<"BENCH tree "<<file<<" round="<<r<<" old="<<a<<" new="<<b<<'\n';
        }
    }
    const auto legacy=[&](int i){gc.gold=i;const auto s=one_combat::richRow(gc,path);std::vector<float> v;v.reserve(1024);std::string cur;for(char c:s){if(c==','){v.push_back(std::strtof(cur.c_str(),nullptr));cur.clear();}else cur+=c;}if(!cur.empty())v.push_back(std::strtof(cur.c_str(),nullptr));return double(v[5]);};
    const auto numeric=[&](int i){gc.gold=i;return double(one_combat::richFeatureVec(gc,path)[5]);};
    for(int r=0;r<5;++r){double a,b;if(r%2){b=timing(numeric);a=timing(legacy);}else{a=timing(legacy);b=timing(numeric);}std::cout<<"BENCH features round="<<r<<" old="<<a<<" new="<<b<<'\n';}
}

